query:
UPDATE sales s
JOIN products p ON s.productId = p.id
SET s.productCategory = p.category
WHERE s.productCategory IS NULL OR s.productCategory = 'individual';

SELECT id, productName, productCategory FROM sales ORDER BY id DESC LIMIT 12;

